import csv,json,re,pathlib,collections
root=pathlib.Path.cwd()
p=root/'@prime'
rows=list(csv.DictReader((p/'UI_MODULES.csv').open(encoding='utf-8-sig',newline='')))
errors=[]
ids=[r['module_id'] for r in rows]
if len(ids)!=len(set(ids)): errors.append('duplicate module IDs')
phase=(p/'UI_PHASES.md').read_text(encoding='utf-8')
main=(p/'PHASES.md').read_text(encoding='utf-8')
plan=(p/'UI_PLAN.md').read_text(encoding='utf-8')
anchors=set()
for h in re.findall(r'^#{1,6} (.+)$',plan,re.M):
 anchors.add(re.sub(r'[^\w\- ]','',h.lower()).replace(' ','-'))
graph={r['module_id']:[d for d in r['depends_on_modules'].split(';') if d] for r in rows}
for r in rows:
 mid=r['module_id']
 exists=(root/r['path']).exists()
 if r['path_state']=='EXISTING' and not exists: errors.append(mid+': missing EXISTING path '+r['path'])
 if r['path_state'] not in ('EXISTING','PROPOSED'): errors.append(mid+': unknown path state')
 for t in filter(None,r['ui_tasks'].split(';')):
  if not re.search(r'(?<![\w-])'+re.escape(t)+r'(?![\w-])',phase): errors.append(mid+': missing task '+t)
 for m in filter(None,r['main_phases'].split(';')):
  if not re.search(r'(?<![\w-])'+re.escape(m)+r'(?![\w-])',main): errors.append(mid+': missing main phase '+m)
 for d in graph[mid]:
  if d not in graph: errors.append(mid+': missing dependency '+d)
 target,anchor=r['plan_anchor'].split('#',1)
 if target!='UI_PLAN.md' or anchor not in anchors: errors.append(mid+': missing anchor '+anchor)
 for source in filter(None,r['demo_sources'].split(';')):
  if not (root/source).exists(): errors.append(mid+': missing demo source '+source)
visited=set();active=set()
def visit(n):
 if n in active: errors.append('cycle at '+n);return
 if n in visited:return
 active.add(n)
 for d in graph.get(n,[]): visit(d)
 active.remove(n);visited.add(n)
for mid in graph:visit(mid)
rust='\n'.join(f.read_text(encoding='utf-8') for parent in [root/'apps/polaris-cli',root/'crates/polaris-ui',root/'crates/polaris-kernel/crates/directives'] for f in parent.rglob('*.rs'))
descriptors=list((root/'specs/descriptors').glob('ui*.json'))
tests=0
for f in descriptors:
 d=json.loads(f.read_text(encoding='utf-8'))
 for field in ['type_of','name','file_path','logic_name','test_list','dependencies','libraries','inputs','output_type','output_description']:
  if field not in d:errors.append(f.name+': missing '+field)
 if not (root/d['file_path']).exists():errors.append(f.name+': missing source '+d['file_path'])
 for t in d['test_list']:
  tests+=1
  if not re.search(r'\bfn\s+'+re.escape(t['test_name'])+r'\b',rust): errors.append(f.name+': test not found '+t['test_name'])
result={'inventory_rows':len(rows),'unique_module_ids':len(set(ids)),'path_states':dict(collections.Counter(r['path_state'] for r in rows)),'statuses':dict(collections.Counter(r['status'] for r in rows)),'acyclic':not any('cycle' in e for e in errors),'descriptors':len(descriptors),'descriptor_test_references':tests,'errors':errors}
print(json.dumps(result,indent=2))
raise SystemExit(bool(errors))

